package com.ftk.tpip.release.domain.model;
import java.time.Instant;import java.util.Objects;
public record WorkspaceAsset(Long id,long workspaceId,WorkspaceAssetType assetType,String assetCode,long assetVersionId,WorkspaceChangeType changeType,String dependencyMetadata,Instant createdAt){public WorkspaceAsset{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");if(workspaceId<=0||assetVersionId<=0)throw new IllegalArgumentException("workspaceId and assetVersionId must be positive");Objects.requireNonNull(assetType);assetCode=Objects.requireNonNull(assetCode).trim();if(assetCode.isEmpty()||assetCode.length()>200)throw new IllegalArgumentException("assetCode is blank or too long");Objects.requireNonNull(changeType);dependencyMetadata=dependencyMetadata==null?"{}":dependencyMetadata;}}
